static int grid[2][50][50];

int main(void) {
    int N, Q;
    if (scanf("%d %d", &N, &Q) != 2) return 0;

    static const int dx[8] = {-1, -1, -1, 0, 0, 1, 1, 1};
    static const int dy[8] = {-1, 0, 1, -1, 1, -1, 0, 1};

    char line[64];
    for (int i = 0; i < N; i++) {
        if (scanf("%63s", line) != 1) return 0;
        for (int j = 0; j < N; j++)
            grid[0][i][j] = line[j] - '0';
    }

    int c = 0;
    for (int step = 0; step < Q; step++) {
        int nc = c ^ 1;
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                int cnt = 0;
                for (int k = 0; k < 8; k++) {
                    int ni = i + dx[k], nj = j + dy[k];
                    if (ni >= 0 && ni < N && nj >= 0 && nj < N)
                        cnt += grid[c][ni][nj];
                }
                if (grid[c][i][j])
                    grid[nc][i][j] = (cnt == 2 || cnt == 3) ? 1 : 0;
                else
                    grid[nc][i][j] = (cnt == 3) ? 1 : 0;
            }
        }
        c = nc;
    }

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++)
            putchar('0' + grid[c][i][j]);
        putchar('\n');
    }
    return 0;
}
